[CmdletBinding()]
param(
  [Parameter(Mandatory)]
  [ValidateSet('primary', 'subagent')]
  [string]$AgentRole,
  [Parameter(Mandatory)]
  [string]$AgentTask,
  [string[]]$ClaimedOwners = @(),
  [switch]$UseRecordedClaim,
  [Parameter(Mandatory)]
  [ValidateRange(1, [int]::MaxValue)]
  [int]$ExpectedRegistryEntryCount,
  [Parameter(Mandatory)]
  [ValidatePattern('^[0-9A-F]{64}$')]
  [string]$ExpectedRegistrySha256,
  [ValidateSet('baseline','cursor_ui','codex_ui','codex_auth','codex_backend','integration_repair','integration')]
  [string]$ProductionLane = 'baseline',
  [ValidateSet(
    'baseline','governance_preflight','coordination_bootstrap','task_start','implementation','pre_commit','handoff',
    'founder_acceptance','ticket_acceptance','ticket_close',
    'integration_start','integration_verify','integration_close','integration_admission_authorize',
    'candidate_preflight'
  )]
  [string]$ProductionPhase = 'baseline',
  [string]$ProductionWorkId,
  [string]$ProductionTicketId,
  [string]$FounderAcceptanceEvidencePath,
  [string]$FounderAcceptanceEvidenceSha256,
  [string]$AcceptedUiCommit,
  [string]$UiContractPath,
  [string]$UiContractSha256,
  [string]$AcceptedTicketCommit,
  [string]$TicketRequirementEvidencePath,
  [string]$TicketRequirementEvidenceSha256,
  [string]$OppoAcceptanceEvidencePath,
  [string]$OppoAcceptanceEvidenceSha256,
  [string[]]$ApprovedFeatureCommits = @(),
  [string[]]$ApprovedFeatureBranches = @(),
  [string]$IntegrationTargetRoot,
  [string]$IntegrationTargetWorkId,
  [string]$IntegrationTargetTicketId,
  [string]$RepositoryRoot
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
if (-not $RepositoryRoot) { $RepositoryRoot = Split-Path -Parent $PSScriptRoot }
$root = [IO.Path]::GetFullPath($RepositoryRoot).TrimEnd([char[]]@('\', '/'))
$workspaceRoot = [IO.Path]::GetFullPath((Split-Path -Parent $root)).TrimEnd(
  [char[]]@('\', '/'))

function Assert-Coordination([bool]$Condition, [string]$Message) {
  if (-not $Condition) {
    throw "Codex subagent coordination gate rejected: $Message"
  }
}

# Founder-approved direct-baseline continuation. No new phases or capture engine.
function Test-OctoberDirectBaselineIdentity([hashtable]$Facts) {
  if ($null -eq $Facts) { return $false }
  $exact = @{
    Root='C:/GUARANTEED OUTCOME/MOOLSOCIAL-WORKTREE-INTEGRATION-REPAIR-store-buy-compatibility-20261008'
    Branch='work/integration-repair/store-buy-compatibility-20261008'
    Role='primary'; Task='/root'; Lane='integration_repair'
    WorkId='store-buy-compatibility-20261008'
    TicketId='UAW-INTEGRATION-REPAIR-STORE-BUY-COMPATIBILITY-20261008'
  }
  $phases=@('task_start','implementation','pre_commit','handoff','integration_admission_authorize')
  if ($Facts.ContainsKey('Lane') -and $Facts.Lane -ceq 'integration') {
    $exact=@{
      Root='C:/GUARANTEED OUTCOME/MOOLSOCIAL-WORKTREE-INTEGRATION-store-buy-combined-baseline-20261008'
      Branch='integration/moolsocial/store-buy-combined-baseline-20261008'
      Role='primary'; Task='/root'; Lane='integration'
      WorkId='store-buy-combined-baseline-20261008'
      TicketId='UAW-INTEGRATION-STORE-BUY-COMBINED-BASELINE-20261008'
    }
    $phases=@('integration_verify','integration_close')
  }
  foreach ($key in $exact.Keys) {
    if (-not $Facts.ContainsKey($key) -or $Facts[$key] -isnot [string] -or
        $Facts[$key] -cne $exact[$key]) { return $false }
  }
  return $Facts.ContainsKey('Phase') -and $Facts.Phase -is [string] -and
    $Facts.Phase -cin $phases
}

