function Read-OctoberCompatibilityScopeRepairAdmission {
  param([string]$Commit,[switch]$FromIndex,[switch]$FromWorkingTree)
  try {
    if(([int]$FromIndex.IsPresent+[int]$FromWorkingTree.IsPresent) -gt 1){return $null}
    if(($FromIndex -or $FromWorkingTree) -and -not [string]::IsNullOrEmpty($Commit)){return $null}
    if(-not $FromIndex -and -not $FromWorkingTree -and $Commit -cnotmatch '\A[0-9a-f]{40}\z'){return $null}
    if([IO.Path]::GetFullPath($root).Replace('\','/').TrimEnd('/') -cne
        'C:/GUARANTEED OUTCOME/MOOLSOCIAL-WORKTREE-INTEGRATION-REPAIR-store-buy-compatibility-20261008'){return $null}
    $owner='docs/quality/STORE-BUY-COMPATIBILITY-20261008.md'
    $text=if($FromWorkingTree){[IO.File]::ReadAllText((Join-Path $root $owner))}
      elseif($FromIndex){@(Get-OctoberCompatibilityGitLines @('show',(':'+$owner))) -join "`n"}
      else{@(Get-OctoberCompatibilityGitLines @('show',($Commit+':'+$owner))) -join "`n"}
    $blocks=[regex]::Matches($text,'(?s)<!-- COMPATIBILITY_SCOPE_REPAIR_JSON_BEGIN -->\s*(.*?)\s*<!-- COMPATIBILITY_SCOPE_REPAIR_JSON_END -->')
    if($blocks.Count -ne 1){return $null}
    $contract=Read-OctoberCompatibilityJsonObject ([Text.Encoding]::UTF8.GetBytes($blocks[0].Groups[1].Value))
    if($null -eq $contract){return $null}
    $canonical=ConvertTo-Json -InputObject $contract -Depth 100 -Compress
    if((Get-OctoberCompatibilityByteHash ([Text.Encoding]::UTF8.GetBytes($canonical))) -cne
        '8BD8DE35E9888FCAB53DD6D34670CBE89B05E6E094896B2C2675E60226E8D8E5'){return $null}
    return $contract
  }catch{return $null}
}

function Read-OctoberCompatibilityTestAdmissionContract {
  param([string]$Commit,[switch]$FromIndex,[switch]$FromWorkingTree)
  # Contract validation is not preparation/commit admission. Operative callers
  # must separately prove immutable N, current writer facts and ordinary scope.
  try {
    if(([int]$FromIndex.IsPresent+[int]$FromWorkingTree.IsPresent) -gt 1){return $null}
    if(([int]$FromIndex.IsPresent+[int]$FromWorkingTree.IsPresent) -eq 1 -and
        -not [string]::IsNullOrEmpty($Commit)){return $null}
    if(-not $FromIndex -and -not $FromWorkingTree -and
        $Commit -cnotmatch '\A[0-9a-f]{40}\z'){return $null}
    if([IO.Path]::GetFullPath($root).Replace('\','/').TrimEnd('/') -cne
        'C:/GUARANTEED OUTCOME/MOOLSOCIAL-WORKTREE-INTEGRATION-REPAIR-store-buy-compatibility-20261008'){return $null}
    $owner='docs/quality/STORE-BUY-COMPATIBILITY-20261008.md'
    $text=if($FromWorkingTree){[IO.File]::ReadAllText((Join-Path $root $owner))}
      elseif($FromIndex){@(Get-OctoberCompatibilityGitLines @('show',(':'+$owner))) -join "`n"}
      else{@(Get-OctoberCompatibilityGitLines @('show',($Commit+':'+$owner))) -join "`n"}
    $blocks=[regex]::Matches($text,'(?s)<!-- COMPATIBILITY_TEST_ADMISSION_JSON_BEGIN -->\s*(.*?)\s*<!-- COMPATIBILITY_TEST_ADMISSION_JSON_END -->')
    if($blocks.Count -ne 1){return $null}
    $contract=Read-OctoberCompatibilityJsonObject ([Text.Encoding]::UTF8.GetBytes($blocks[0].Groups[1].Value))
    if($null -eq $contract){return $null}
    $canonical=ConvertTo-Json -InputObject $contract -Depth 100 -Compress
    if((Get-OctoberCompatibilityByteHash ([Text.Encoding]::UTF8.GetBytes($canonical))) -cne
        'A27A195444E4295FA218F549EC4D978AF77605AA344C35B7D3A44CE783EAA889'){return $null}
    return $contract
  }catch{return $null}
}

function Test-OctoberCompatibilityIntegrationIdentity([hashtable]$Facts) {
  $expected=@{
    Role='primary'; Task='/root'; Lane='integration'
    Root='C:/GUARANTEED OUTCOME/MOOLSOCIAL-WORKTREE-INTEGRATION-store-buy-combined-baseline-20261008'
    Branch='integration/moolsocial/store-buy-combined-baseline-20261008'
    WorkId='store-buy-combined-baseline-20261008'
    TicketId='UAW-INTEGRATION-STORE-BUY-COMBINED-BASELINE-20261008'
  }
  foreach($key in $expected.Keys) {
    if(-not $Facts.ContainsKey($key) -or [string]$Facts[$key] -cne $expected[$key]) { return $false }
  }
  # Before merge, the source-side admission validates the governance-tag target.
  # This identity admits only the inherited checker after the automatic merge.
  return $Facts.ContainsKey('Phase') -and [string]$Facts.Phase -cin
    @('integration_verify','integration_close','candidate_preflight')
}

function Test-OctoberCompatibilityBindingInventory {
  param([object[]]$Bindings, [object[]]$BaseBindings)
  if ($Bindings.Count -ne 83 -or $BaseBindings.Count -ne 82) { return $false }
  $expected=@{}
  foreach ($binding in $BaseBindings) {
    $id=[string]$binding.id
    if ([string]::IsNullOrWhiteSpace($id) -or $expected.ContainsKey($id)) { return $false }
    $expected[$id]=ConvertTo-Json -InputObject $binding -Depth 100 -Compress
  }
  $successor=Get-OctoberCompatibilityBinding
  if ($expected.ContainsKey($successor.id)) { return $false }
  $expected[$successor.id]=ConvertTo-Json -InputObject $successor -Depth 100 -Compress
  $seen=@{}
  foreach ($binding in $Bindings) {
    $id=[string]$binding.id
    if (-not $expected.ContainsKey($id) -or $seen.ContainsKey($id)) { return $false }
    if ((ConvertTo-Json -InputObject $binding -Depth 100 -Compress) -cne $expected[$id]) {
      return $false
    }
    $seen[$id]=$true
  }
  return $seen.Count -eq 83
}

function Get-OctoberCompatibilityGitLines([string[]]$Arguments) {
  $lines=@(& git --no-pager --no-optional-locks --no-replace-objects -C $root @Arguments)
  Assert-Coordination ($LASTEXITCODE -eq 0) 'Compatibility Git evidence read failed.'
  return $lines
}

function Get-OctoberCompatibilityHistoryStage([string]$HeadCommit) {
  $binding=Get-OctoberCompatibilityBinding
  $mergePath=@(Get-OctoberCompatibilityGitLines @('rev-parse','--path-format=absolute','--git-path','MERGE_HEAD'))
  Assert-Coordination ($mergePath.Count -eq 1 -and
    -not (Test-Path -LiteralPath $mergePath[0])) 'Compatibility rejects any pending merge before bootstrap, implementation or handoff.'
  $store='8002e8cd740aaf613b75dc749212fb12ae4fddb7'
  $cursor='f32c17e1a3a41807564fe18f83c0520a66e0bfe6'
  $b='55b87b8a590a991fdec198d9386f964292bea047'
  $p='f27e25fdfa64453d119d81dcef51956a56120c19'
  $r='6fc0cb5b5ef0f58897c4576651e3208e69076b4c'
  $e=[string]$binding.baselineHead
  Assert-Coordination ($HeadCommit -cmatch '^[0-9a-f]{40}$') 'Compatibility HEAD identity invalid.'
  foreach($pair in @(@($b,$store),@($p,$b),@($r,"$p $cursor"),@($e,$r))) {
    $parents=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%P',[string]$pair[0]))
    Assert-Coordination ($parents.Count -eq 1 -and $parents[0] -ceq $pair[1]) 'Sealed B/P/R/E parentage changed.'
  }
  $rTree=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%T',$r))
  Assert-Coordination ($rTree.Count -eq 1 -and $rTree[0] -ceq
    '8ebeb477651a294d1a8f1d10175aa562f6cb6415') 'Sealed nine-owner repair tree changed.'
  foreach($docCommit in @($p,$e)) {
    $owners=@(Get-OctoberCompatibilityGitLines @('diff-tree','--no-commit-id','--name-only','-r',$docCommit))
    Assert-Coordination ($owners.Count -eq 1 -and $owners[0] -ceq
      'docs/quality/STORE-BUY-COMBINED-REPAIR-20261008.md') 'Sealed documentary checkpoint changed source.'
  }
  $bApps=@(Get-OctoberCompatibilityGitLines @('rev-parse',"${b}:apps","${store}:apps"))
  $eApps=@(Get-OctoberCompatibilityGitLines @('rev-parse',"${e}:apps","${r}:apps"))
  Assert-Coordination ($bApps.Count -eq 2 -and $bApps[0] -ceq $bApps[1] -and
    $eApps.Count -eq 2 -and $eApps[0] -ceq $eApps[1]) 'Sealed metadata checkpoint changed apps.'
  & git -C $root merge-base --is-ancestor $e $HeadCommit
  Assert-Coordination ($LASTEXITCODE -eq 0) 'Compatibility HEAD must descend from exact E.'
  $commits=@(Get-OctoberCompatibilityGitLines @('rev-list','--reverse',"$e..$HeadCommit"))
  $firstParent=@(Get-OctoberCompatibilityGitLines @('rev-list','--first-parent','--reverse',"$e..$HeadCommit"))
  Assert-Coordination ($commits.Count -le 32 -and
    ($commits -join '|') -ceq ($firstParent -join '|')) 'Compatibility history contains an extra commit or merge.'
  $previous=$e
  $subjects=@($binding.bootstrapCommitSubject,
    'repair(store-buy-compatibility-20261008): align Store publication with sealed Buy contracts',
    'coordination(store-buy-compatibility-20261008): admit exact handoff audit correction',
    'coordination(store-buy-compatibility-20261008): admit exact qualification coverage',
    'coordination(store-buy-compatibility-20261008): admit exact stale handover protection',
    'coordination(store-buy-compatibility-20261008): admit exact coverage and embedded Cart repair',
    'coordination(store-buy-compatibility-20261008): admit exclusive embedded Buy handoff',
    'repair(store-buy-compatibility-20261008): align approved Store layout journeys',
    'coordination(store-buy-compatibility-20261008): admit exact inherited Cart test repair',
    'repair(store-buy-compatibility-20261008): align inherited Cart tests with accepted contracts',
    'coordination(store-buy-compatibility-20261008): admit strict retention compatibility',
    'repair(store-buy-compatibility-20261008): preserve optional retention fields under strict mode',
    'coordination(store-buy-compatibility-20261008): admit exact forward layout test repair',
    'coordination(store-buy-compatibility-20261008): admit scoped purchase return recovery',
    'coordination(store-buy-compatibility-20261008): admit exact scoped search and purchase repair',
    'repair(store-buy-compatibility-20261008): preserve purchase return and scoped search journeys',
    'coordination(store-buy-compatibility-20261008): admit current frontend qualification contract',
    'repair(store-buy-compatibility-20261008): align current qualification capture callers',
    'qualification(store-buy-compatibility-20261008): verify current frontend source with provider deferrals')
  $forward=$null
  if($commits.Count -ge 19) {
    $nextSubject=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%s',([string]$commits[18])))
    if($nextSubject.Count -eq 1 -and $nextSubject[0] -ceq
        'coordination(store-buy-compatibility-20261008): admit exact Source17 coordinate correction') {
      $forward=Read-OctoberCompatibilitySource17ForwardAmendment -Commit ([string]$commits[18])
      Assert-Coordination ($null -ne $forward -and
        $commits[16] -ceq '0d487b454cc515ed980eec2f48962846f1314994' -and
        $commits[17] -ceq $forward.predecessorCommit) 'Forward amendment requires the exact sealed Source16/17 history.'
      $subjects=@($subjects[0..17])+@($forward.chain | ForEach-Object {[string]$_.subject})
    }else{
      Assert-Coordination ($commits.Count -le 19) 'Original qualification graph cannot admit forward successors.'
    }
  }
  $source19Forward=$null
  if($commits.Count -ge 21 -and $null -ne $forward) {
    $nextSubject=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%s',([string]$commits[20])))
    if($nextSubject.Count -eq 1 -and $nextSubject[0] -ceq 'coordination(store-buy-compatibility-20261008): admit exact current obligation qualification') {
      $source19Forward=Read-OctoberCompatibilitySource19ForwardAmendment -Commit ([string]$commits[20])
      Assert-Coordination ($null -ne $source19Forward -and
        $commits[18] -ceq 'd50dab60b440bd7caaff312a8f037ba63759461a' -and
        $commits[19] -ceq $source19Forward.predecessorCommit) 'Current obligation amendment requires exact Source18/19 history.'
      $forward=$forward|ConvertTo-Json -Depth 30 -Compress|ConvertFrom-Json
      $forward.chain=@($forward.chain[0..1])+@($source19Forward.chain)
      $subjects=@($subjects[0..19])+@($source19Forward.chain|ForEach-Object {[string]$_.subject})
    }else{Assert-Coordination ($commits.Count -le 21) 'Source17 qualification cannot admit later successors.'}
  }
  $source21Forward=$null
  if($commits.Count -ge 23 -and $null -ne $source19Forward) {
    $nextSubject=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%s',([string]$commits[22])))
    if($nextSubject.Count -eq 1 -and $nextSubject[0] -ceq 'coordination(store-buy-compatibility-20261008): admit exact Store capture callback correction') {
      $source21Forward=Read-OctoberCompatibilitySource21ForwardAmendment -Commit ([string]$commits[22])
      Assert-Coordination ($null -ne $source21Forward -and
        $commits[20] -ceq '5b63801ad478491f24e4235c79dfb4f7208dd2c6' -and
        $commits[21] -ceq $source21Forward.predecessorCommit) 'Capture callback amendment requires exact Source20/21 history.'
      $forward=$forward|ConvertTo-Json -Depth 30 -Compress|ConvertFrom-Json
      $forward.chain=@($forward.chain[0..3])+@($source21Forward.chain)
      $subjects=@($subjects[0..21])+@($source21Forward.chain|ForEach-Object {[string]$_.subject})
    }else{
      # Preserve the earlier sealed Q graph grammar, not its qualification.
      # Current Source21 preparation cannot commit Q directly, and failed/missing
      # native evidence remains rejected by the unchanged qualification reader.
      Assert-Coordination ($commits.Count -eq 23 -and $nextSubject.Count -eq 1 -and
        $nextSubject[0] -ceq $source19Forward.chain[2].subject) 'Source21 qualification cannot admit later successors.'
    }
  }
  $source23Forward=$null
  if($commits.Count -ge 25 -and $null -ne $source21Forward) {
    $nextSubject=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%s',([string]$commits[24])))
    if($nextSubject.Count -eq 1 -and $nextSubject[0] -ceq 'coordination(store-buy-compatibility-20261008): admit exact stored-order capture correction') {
      $source23Forward=Read-OctoberCompatibilitySource23ForwardAmendment -Commit ([string]$commits[24])
      Assert-Coordination ($null -ne $source23Forward -and
        $commits[22] -ceq '9a11c6f9c788bd62f515a90db583abec83051207' -and
        $commits[23] -ceq $source23Forward.predecessorCommit) 'Stored-order amendment requires exact Source22/23 history.'
      $forward=$forward|ConvertTo-Json -Depth 30 -Compress|ConvertFrom-Json
      $forward.chain=@($forward.chain[0..5])+@($source23Forward.chain)
      $subjects=@($subjects[0..23])+@($source23Forward.chain|ForEach-Object {[string]$_.subject})
    }else{
      Assert-Coordination ($commits.Count -eq 25 -and $nextSubject.Count -eq 1 -and
        $nextSubject[0] -ceq $source21Forward.chain[2].subject) 'Source23 qualification cannot admit later successors.'
    }
  }
  $source25Forward=$null
  if($commits.Count -ge 27 -and $null -ne $source23Forward) {
    $nextSubject=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%s',([string]$commits[26])))
    if($nextSubject.Count -eq 1 -and $nextSubject[0] -ceq 'coordination(store-buy-compatibility-20261008): admit exact capture context and current navigation') {
      $source25Forward=Read-OctoberCompatibilitySource25ForwardAmendment -Commit ([string]$commits[26])
      Assert-Coordination ($null -ne $source25Forward -and
        $commits[24] -ceq '0aa47c1b68e27067f0f8c2ecce1e2bfebaf7a86a' -and
        $commits[25] -ceq $source25Forward.predecessorCommit) 'Capture context amendment requires exact Source24/25 history.'
      $forward=$forward|ConvertTo-Json -Depth 30 -Compress|ConvertFrom-Json
      $forward.chain=@($forward.chain[0..7])+@($source25Forward.chain)
      $subjects=@($subjects[0..25])+@($source25Forward.chain|ForEach-Object {[string]$_.subject})
    }else{
      Assert-Coordination ($commits.Count -eq 27 -and $nextSubject.Count -eq 1 -and
        $nextSubject[0] -ceq $source23Forward.chain[2].subject) 'Source25 qualification cannot admit later successors.'
    }
  }
  $source27Forward=$null
  if($commits.Count -ge 29 -and $null -ne $source25Forward) {
    $nextSubject=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%s',([string]$commits[28])))
    if($nextSubject.Count -eq 1 -and $nextSubject[0] -ceq 'coordination(store-buy-compatibility-20261008): admit exact current evidence evaluator binding') {
      $source27Forward=Read-OctoberCompatibilitySource27ForwardAmendment -Commit ([string]$commits[28])
      Assert-Coordination ($null -ne $source27Forward -and
        $commits[26] -ceq '971897c27d3f07ff8fe429c16c962ceeb823d580' -and
        $commits[27] -ceq $source27Forward.predecessorCommit) 'Evaluator amendment requires exact Source26/27 history.'
      $forward=$forward|ConvertTo-Json -Depth 30 -Compress|ConvertFrom-Json
      $forward.chain=@($forward.chain[0..9])+@($source27Forward.chain)
      $subjects=@($subjects[0..27])+@($source27Forward.chain|ForEach-Object {[string]$_.subject})
    }else{
      Assert-Coordination ($commits.Count -eq 29 -and $nextSubject.Count -eq 1 -and
        $nextSubject[0] -ceq $source25Forward.chain[2].subject) 'Source27 qualification cannot admit arbitrary later successors.'
    }
  }
  $source28Forward=$null
  if($commits.Count -ge 30 -and $null -ne $source27Forward) {
    $nextSubject=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%s',([string]$commits[29])))
    if($nextSubject.Count -eq 1 -and $nextSubject[0] -ceq 'coordination(store-buy-compatibility-20261008): admit exact operational scenario capture correction') {
      $source28Forward=Read-OctoberCompatibilitySource28ForwardAmendment -Commit ([string]$commits[29])
      Assert-Coordination ($null -ne $source28Forward -and $commits[28] -ceq $source28Forward.predecessorCommit) 'Operational capture amendment requires exact evaluator28 history.'
      $predecessor=@(Get-OctoberCompatibilityGitLines @('rev-parse',($commits[28]+'^{tree}'),($commits[28]+':apps'),($commits[28]+':apps/mobile/lib'),($commits[28]+':apps/mobile/test/work_workspace_layout_safety_test.dart')))
      Assert-Coordination ($predecessor.Count -eq 4 -and $predecessor[0] -ceq $source28Forward.predecessorTree -and
        $predecessor[1] -ceq $source28Forward.frozenAppsTree -and $predecessor[2] -ceq $source28Forward.frozenRuntimeTree -and
        $predecessor[3] -ceq $source28Forward.layoutPredecessorBlob) 'Operational capture predecessor source changed.'
      $forward=$forward|ConvertTo-Json -Depth 30 -Compress|ConvertFrom-Json
      $forward.chain=@($forward.chain[0..10])+@($source28Forward.chain)
      $subjects=@($subjects[0..28])+@($source28Forward.chain|ForEach-Object {[string]$_.subject})
    }else{
      Assert-Coordination ($commits.Count -eq 30 -and $nextSubject.Count -eq 1 -and
        $nextSubject[0] -ceq $source27Forward.chain[1].subject) 'Evaluator qualification cannot admit arbitrary later successors.'
    }
  }
  Assert-Coordination ($commits.Count -le 30 -or $null -ne $source28Forward) 'Count31/32 requires independently verified operational capture history.'
  for($index=0;$index -lt $commits.Count;$index++) {
    $commit=[string]$commits[$index]
    $parents=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%P',$commit))
    $subject=@(Get-OctoberCompatibilityGitLines @('show','-s','--format=%s',$commit))
    Assert-Coordination ($parents.Count -eq 1 -and $parents[0] -ceq $previous -and
      $subject.Count -eq 1 -and $subject[0] -ceq $subjects[$index]) 'Compatibility successor parent/subject changed.'
    $owners=@(Get-OctoberCompatibilityGitLines @('diff-tree','--no-commit-id','--name-only','-r',$commit))
    $expected=if($index -eq 0){@($binding.bootstrapOwners)}
      elseif($index -eq 1){@(Get-OctoberCompatibilityApplicationOwners)}
      elseif($index -in @(2,3,4,5,6,8,10,12,13,14,16)){@(Get-OctoberCompatibilityAmendmentOwners)}
      elseif($index -eq 7){@(Get-OctoberCompatibilityCoverageCartOwners)}
      elseif($index -eq 9){@(Get-OctoberCompatibilityInheritedCartTestOwners)}
      elseif($index -eq 11){@(Get-OctoberCompatibilityRetentionOwners)}
      elseif($index -eq 15){@(Get-OctoberCompatibilityScrollRepairOwners)}
      elseif($null -ne $forward -and $index -ge 18){@($forward.chain[$index-18].owners)}
      elseif($index -eq 17){@('apps/mobile/test/work_workspace_layout_safety_test.dart')}
      else{@('docs/quality/STORE-BUY-COMPATIBILITY-20261008.md')}
    Assert-Coordination ((@($owners | Sort-Object) -join '|') -ceq
      (@($expected | Sort-Object) -join '|')) 'Compatibility successor changed unexpected owners.'
    if($index -in @(0,2,3,4,5,6,8,10,11,12,13,14,16,18) -or
       ($null -ne $forward -and $index -eq 20) -or ($null -ne $source19Forward -and $index -eq 22) -or
       ($null -ne $source21Forward -and $index -eq 24) -or
       ($null -ne $source23Forward -and $index -eq 26) -or
       ($null -ne $source25Forward -and $index -eq 28) -or
       ($null -ne $source27Forward -and $index -eq 29) -or
       ($null -ne $source28Forward -and $index -eq 31)) {
      $apps=@(Get-OctoberCompatibilityGitLines @('rev-parse',"${commit}:apps","${previous}:apps"))
      Assert-Coordination ($apps.Count -eq 2 -and $apps[0] -ceq $apps[1]) 'Compatibility metadata commit changed apps.'
    }
    $previous=$commit
  }
  if($commits.Count -ge 1) {
    Assert-Coordination ($commits[0] -ceq 'f376a80b9c4abb6bed42ebb40136de2dd884d346') 'Sealed compatibility G changed.'
  }
  if($commits.Count -ge 2) {
    Assert-Coordination ($commits[1] -ceq '62e0a37d900f11c0c2d405e6559e54ef70ab9b43') 'Sealed compatibility C changed.'
  }
  if($commits.Count -ge 3) {
    Assert-Coordination ($commits[2] -ceq '8e711da618ed9b04b9a9e267b5d4b5c7400b02fe') 'Sealed compatibility A changed.'
  }
  if($commits.Count -ge 4) {
    Assert-Coordination ($commits[3] -ceq '7ccc0f01372276f6bc0b654544c95fc56c7b7086') 'Sealed compatibility H changed.'
  }
  if($commits.Count -ge 5) {
    Assert-Coordination ($commits[4] -ceq '84b889430abb84e67ea1cf3838c63841429f7712') 'Sealed compatibility J changed.'
  }
  if($commits.Count -ge 6) {
    Assert-Coordination ($commits[5] -ceq '2beaf3775ed20f14fa42101346b35ddb7f8e9283') 'Sealed compatibility K changed.'
  }
  if($commits.Count -ge 7) {
    # Immutable commit only: working/index documents cannot activate M.
    Assert-Coordination ($commits[6] -ceq '122d9f12bde7baea38eeb30dada3b1321e3d5289') 'Sealed compatibility M changed.'
    $handoff=Get-OctoberCompatibilityClaimHandoff -Commit ([string]$commits[6])
    Assert-Coordination ($null -ne $handoff -and
      $handoff.Sha256 -ceq 'B2EE65275AF1A0BD2F176751EDA97C3493A1858CFB0B5588AED52D092D1DA505' -and
      $handoff.Contract.predecessorCommit -ceq $commits[5]) 'Committed compatibility M handoff contract missing or changed.'
  }
  if($commits.Count -ge 8) {
    Assert-Coordination ($commits[7] -ceq '0da3630d1c857390c173ec83ba5c0210cb1e5ec2') 'Sealed compatibility L5 changed.'
  }
  if($commits.Count -ge 9) {
    # Only an immutable N contract admits the subsequent exact four test owners.
    $testAdmission=Read-OctoberCompatibilityTestAdmissionContract -Commit ([string]$commits[8])
    Assert-Coordination ($null -ne $testAdmission -and
      $testAdmission.predecessorCommit -ceq $commits[7]) 'Committed N test admission missing or changed.'
  }
  if($commits.Count -ge 10) {
    Assert-Coordination ($commits[9] -ceq '4d1b314b4f41b329998a65886cf459d18a9a12e2') 'Sealed compatibility T changed.'
  }
  if($commits.Count -ge 11) {
    Assert-Coordination ($commits[10] -ceq '660c4c17f03d28a2a14cad668e16f91445b610e2') 'Sealed compatibility U changed.'
  }
  if($commits.Count -ge 12) {
    Assert-Coordination ($commits[11] -ceq 'aecfa68c1beb3517d57306ff7a596c539f8fe10b') 'Sealed compatibility V changed.'
  }
  if($commits.Count -ge 13) {
    Assert-Coordination ($commits[12] -ceq '5a70a1728d534f72c06997d6c7146a46fa7481cf') 'Sealed compatibility W changed.'
  }
  if($commits.Count -ge 14) {
    Assert-Coordination ($commits[13] -ceq 'b25e5913d088cc49b8c0fe40623cef49778e462a') 'Sealed compatibility B25 changed.'
  }
  if($commits.Count -ge 15) {
    $scopeAdmission=Read-OctoberCompatibilityScopeRepairAdmission -Commit ([string]$commits[14])
    Assert-Coordination ($null -ne $scopeAdmission -and
      $scopeAdmission.predecessorCommit -ceq $commits[13]) 'Immutable scoped repair admission missing or changed.'
  }
  if($commits.Count -ge 16) {
    Assert-Coordination ($commits[15] -ceq '3c3f38136db8bb184866635203d04ea4643f1eac') 'Sealed Source15 runtime/test checkpoint changed.'
  }
  if($commits.Count -ge 17) {
    $current=Read-OctoberCompatibilityCurrentSuccessorSpecification -Commit ([string]$commits[16])
    Assert-Coordination ($null -ne $current) 'Immutable current successor specification missing or changed.'
    $layout=@(Get-OctoberCompatibilityGitLines @('rev-parse',($commits[16]+':apps/mobile/test/work_workspace_layout_safety_test.dart')))
    Assert-Coordination ($layout.Count -eq 1 -and $layout[0] -ceq 'd03a41613b82dfb01d2c55cf57ae5cb7fc34bb2a') 'Current metadata changed the scoped layout predecessor.'
    $originalEnd=if($null -ne $forward){18}else{$commits.Count}
    for($currentIndex=16;$currentIndex -lt $originalEnd;$currentIndex++) {
      $entry=$current.chain[$currentIndex-16]
      Assert-Coordination ($entry.index -eq $currentIndex -and $entry.subject -ceq $subjects[$currentIndex]) 'Current successor graph differs from its immutable contract.'
      $currentContract=Read-OctoberCompatibilityCurrentSuccessorSpecification -Commit ([string]$commits[$currentIndex])
      Assert-Coordination ($null -ne $currentContract) 'Current successor lost or changed its immutable contract.'
    }
    if($null -ne $forward) {
      foreach($currentIndex in 18..($commits.Count-1)) {
        $entry=$forward.chain[$currentIndex-18]
        Assert-Coordination ($entry.index -eq $currentIndex -and $entry.parentIndex -eq ($currentIndex-1) -and
          $entry.subject -ceq $subjects[$currentIndex] -and
          $null -ne (Read-OctoberCompatibilitySource17ForwardAmendment -Commit ([string]$commits[$currentIndex]))) 'Forward successor lost its original or appended immutable contract.'
        if($currentIndex -ge 20 -and $null -ne $source19Forward) {
          Assert-Coordination ($null -ne (Read-OctoberCompatibilitySource19ForwardAmendment -Commit ([string]$commits[$currentIndex]))) 'Current obligation successor lost its sealed forward contract.'
        }
        if($currentIndex -ge 22 -and $null -ne $source21Forward) {
          Assert-Coordination ($null -ne (Read-OctoberCompatibilitySource21ForwardAmendment -Commit ([string]$commits[$currentIndex]))) 'Capture callback successor lost its sealed forward contract.'
        }
        if($currentIndex -ge 24 -and $null -ne $source23Forward) {
          Assert-Coordination ($null -ne (Read-OctoberCompatibilitySource23ForwardAmendment -Commit ([string]$commits[$currentIndex]))) 'Stored-order successor lost its sealed forward contract.'
        }
        if($currentIndex -ge 26 -and $null -ne $source25Forward) {
          Assert-Coordination ($null -ne (Read-OctoberCompatibilitySource25ForwardAmendment -Commit ([string]$commits[$currentIndex]))) 'Capture context successor lost its sealed forward contract.'
        }
        if($currentIndex -ge 28 -and $null -ne $source27Forward) {
          Assert-Coordination ($null -ne (Read-OctoberCompatibilitySource27ForwardAmendment -Commit ([string]$commits[$currentIndex]))) 'Evaluator successor lost its sealed forward contract.'
        }
        if($currentIndex -ge 29 -and $null -ne $source28Forward) {
          Assert-Coordination ($null -ne (Read-OctoberCompatibilitySource28ForwardAmendment -Commit ([string]$commits[$currentIndex]))) 'Operational capture successor lost its sealed forward contract.'
        }
        $runtime=@(Get-OctoberCompatibilityGitLines @('rev-parse',($commits[$currentIndex]+':apps/mobile/lib'),
          '3c3f38136db8bb184866635203d04ea4643f1eac:apps/mobile/lib'))
        Assert-Coordination ($runtime.Count -eq 2 -and $runtime[0] -ceq $runtime[1]) 'Forward test/qualification correction changed frozen runtime.'
      }
    }
  }
  if($commits.Count -ge 18) {
    $runtime=@(Get-OctoberCompatibilityGitLines @('rev-parse',($commits[17]+':apps/mobile/lib'),'3c3f38136db8bb184866635203d04ea4643f1eac:apps/mobile/lib'))
    Assert-Coordination ($runtime.Count -eq 2 -and $runtime[0] -ceq $runtime[1]) 'Capture caller correction changed frozen runtime source.'
  }
  Assert-Coordination ($previous -ceq $HeadCommit) 'Compatibility tip does not match complete successor history.'
  # Keep physical commit count separate from qualification phase. In particular,
  # forward Stage19 is the admitted test-edit phase, never old Stage19 closure.
  $source17Preparation=$commits.Count -eq 18 -and
    $HeadCommit -ceq '737eea29357d5f42375b865754f3762f10545e37'
  $source19Preparation=$commits.Count -eq 20 -and $HeadCommit -ceq '51b3dc076ab10ff4f233a420791e4d2b25d2512a'
  $source21Preparation=$commits.Count -eq 22 -and $HeadCommit -ceq '43ea27a81e7c1876abc0df15b39342da96b63c10'
  $source23Preparation=$commits.Count -eq 24 -and $HeadCommit -ceq '880eea8fa679712ce800f2408e264de1ef75a198'
  $source25Preparation=$commits.Count -eq 26 -and $HeadCommit -ceq '17fb46dcbd22271e8ba495f1aada24ba5f746360'
  $source27Preparation=$commits.Count -eq 28 -and $HeadCommit -ceq 'a03eff1c0e37cc71d0c9bd26d2724de12e63a2d3'
  $source28Preparation=$commits.Count -eq 29 -and $HeadCommit -ceq 'fbf31fea1e6f4375f3e828259b26abe145cd20ef'
  $phaseStage=if($null -ne $source28Forward){[int]$commits.Count-13}elseif($source28Preparation){16}elseif($null -ne $source27Forward){[int]$commits.Count-11}elseif($source27Preparation){16}elseif($null -ne $source25Forward){[int]$commits.Count-10}elseif($source25Preparation){16}elseif($null -ne $source23Forward){[int]$commits.Count-8}elseif($source23Preparation){16}elseif($null -ne $source21Forward){[int]$commits.Count-6}elseif($source21Preparation){16}elseif($null -ne $source19Forward){[int]$commits.Count-4}elseif($source19Preparation){16}elseif($null -ne $forward){[int]$commits.Count-2}elseif($source17Preparation){16}else{[int]$commits.Count}
  $contractIndex=if($null -ne $source28Forward){29}elseif($null -ne $source25Forward){26}elseif($null -ne $source23Forward){24}elseif($null -ne $source21Forward){22}elseif($null -ne $source19Forward){20}elseif($null -ne $forward){18}else{16}
  $captureIndex=$contractIndex+1
  return @{Stage=[int]$commits.Count;Commits=$commits;Base=$e;Head=$HeadCommit;
    PhaseStage=$phaseStage;Source17Preparation=$source17Preparation;Source19Preparation=$source19Preparation;Source19Forward=($null -ne $source19Forward);Forward=($null -ne $forward);
    Source21Preparation=$source21Preparation;Source21Forward=($null -ne $source21Forward);
    Source23Preparation=$source23Preparation;Source23Forward=($null -ne $source23Forward);
    Source25Preparation=$source25Preparation;Source25Forward=($null -ne $source25Forward);
    Source27Preparation=$source27Preparation;Source27Forward=($null -ne $source27Forward);
    Source28Preparation=$source28Preparation;Source28Forward=($null -ne $source28Forward);
    ContractIndex=$contractIndex;CaptureIndex=$captureIndex;
    QualificationIndex=$(if($null -ne $source28Forward){31}elseif($null -ne $source27Forward){29}else{$captureIndex+1});
    QualificationBaseIndex=$(if($null -ne $source28Forward){29}elseif($null -ne $source27Forward){28}else{$contractIndex})}
}

function Get-OctoberCompatibilityReportPlan([string]$ReportId) {
  $suites=switch -CaseSensitive ($ReportId) {
    'publication_contracts' { @('work_invoice_pdf_test.dart','work_downloads_test.dart',
      'work_public_handoff_test.dart','work_publication_test.dart','work_product_content_test.dart',
      'review_auth_persistence_test.dart','ui_v2/buy/buy_v2_catalogue_preview_test.dart',
      'ui_v2/buy/buy_v2_catalogue_copy_hierarchy_test.dart') }
    'impacted_store_buy' { @('retailer_pos_vertical_slice_test.dart','work_store_atomic_operations_test.dart',
      'work_store_publication_settings_test.dart','social_create_draft_repository_test.dart',
      'ui_v2/buy/buy_v2_scoped_cart_checkout_dock_continuity_test.dart',
      'ui_v2/buy/buy_v2_cart_safe_clear_test.dart','ui_v2/buy/buy_v2_navigation_motion_test.dart',
      'ui_v2/buy/buy_v2_cart_line_continuity_test.dart','ui_v2/buy/buy_v2_checkout_cart_return_continuity_test.dart') }
    'store_layout_and_recovery' { @('work_workspace_layout_safety_test.dart') }
    'enabled_review_fixture' { @('work_store_atomic_operations_test.dart') }
    default { return $null }
  }
  $defines=if($ReportId -ceq 'enabled_review_fixture'){
    @('MOOLSOCIAL_DEVICE_REVIEW=true','MOOLSOCIAL_UI_REVIEW_ONLY=true')
  }else{@()}
  $arguments=@('test','--no-pub','--reporter=json')+@($suites | ForEach-Object {'test/'+$_})+
    @($defines | ForEach-Object {'--dart-define='+$_})
  if($ReportId -ceq 'enabled_review_fixture') {
    $arguments+=@('--name=^COUNTERRELAUNCH review Store recovery ')
  }
  return @{Id=$ReportId; Suites=@($suites); RuntimeDefines=@($defines); Arguments=$arguments}
}

