    # a working document or a caller-supplied command-line authority flag.
    if(-not $Facts.ContainsKey('NTestAdmissionVerified') -or
        $Facts.NTestAdmissionVerified -isnot [bool] -or -not $Facts.NTestAdmissionVerified){return $false}
  }
  if($Facts.Stage -eq 5 -and [string]$Facts.Phase -cin @('implementation','pre_commit')) {
    if(-not $Facts.ContainsKey('KPreparationVerified') -or
        $Facts.KPreparationVerified -isnot [bool] -or -not $Facts.KPreparationVerified){return $false}
    if([string]$Facts.Phase -ceq 'pre_commit' -and
        (-not $Facts.ContainsKey('KResolutionVerified') -or
         $Facts.KResolutionVerified -isnot [bool] -or -not $Facts.KResolutionVerified)){return $false}
  }
  if($Facts.Stage -eq 4 -and [string]$Facts.Phase -cin @('implementation','pre_commit')) {
    if(-not $Facts.ContainsKey('JPreparationVerified') -or
        $Facts.JPreparationVerified -isnot [bool] -or -not $Facts.JPreparationVerified) { return $false }
  }
  # H must fail closed until its live preservation/admission collector supplies
  # the exact independently checked preparation fact. No CLI boolean override.
  if($Facts.Stage -eq 3 -and [string]$Facts.Phase -cin @('implementation','pre_commit')) {
    if(-not $Facts.ContainsKey('HPreparationVerified') -or
        $Facts.HPreparationVerified -isnot [bool] -or
        -not $Facts.HPreparationVerified) { return $false }
    # Publication of H is still blocked until the exact coverage specification
    # is validated internally. Preparation alone is not commit authority.
    if([string]$Facts.Phase -ceq 'pre_commit' -and
        (-not $Facts.ContainsKey('HCoverageVerified') -or
        $Facts.HCoverageVerified -isnot [bool] -or -not $Facts.HCoverageVerified)) { return $false }
  }
  if($Facts.Stage -eq 6) {
    # Internally collected preparation facts are not yet wired; absent/false or
    # coerced values must fail closed. K alone never transfers the Buy claim.
    if(-not $Facts.ContainsKey('MPreparationVerified') -or
        $Facts.MPreparationVerified -isnot [bool] -or -not $Facts.MPreparationVerified){return $false}
    if([string]$Facts.Phase -ceq 'pre_commit' -and
        (-not $Facts.ContainsKey('MContractVerified') -or
        $Facts.MContractVerified -isnot [bool] -or -not $Facts.MContractVerified)){return $false}
  }
  switch -CaseSensitive ([string]$Facts.Phase) {
    'coordination_bootstrap' {
      if ($Facts.Stage -ne 0) { return $false }
      $expectedOwners=@($binding.bootstrapOwners)
    }
    'pre_commit' {
      switch ($Facts.Stage) {
        0 { $expectedOwners=@($binding.bootstrapOwners) }
        1 { $expectedOwners=@(Get-OctoberCompatibilityApplicationOwners) }
        2 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        3 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        4 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        5 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        6 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        7 { $expectedOwners=@(Get-OctoberCompatibilityCoverageCartOwners) }
        8 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        9 { $expectedOwners=@(Get-OctoberCompatibilityInheritedCartTestOwners) }
        10 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        11 { $expectedOwners=@(Get-OctoberCompatibilityRetentionOwners) }
        12 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        13 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        14 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        15 { $expectedOwners=@(Get-OctoberCompatibilityScrollRepairOwners) }
        16 { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
        17 { $expectedOwners=@('apps/mobile/test/work_workspace_layout_safety_test.dart') }
        18 { $expectedOwners=@('docs/quality/STORE-BUY-COMPATIBILITY-20261008.md') }
        default { return $false }
      }
    }
    'task_start' {
      if ($Facts.Stage -ne 1 -or -not $Facts.ContainsKey('Clean') -or
          $Facts.Clean -isnot [bool] -or -not $Facts.Clean) { return $false }
      $expectedOwners=@(Get-OctoberCompatibilityApplicationOwners)
    }
    'implementation' {
      if ($Facts.Stage -eq 1) { $expectedOwners=@(Get-OctoberCompatibilityApplicationOwners) }
      elseif ($Facts.Stage -eq 2) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 3) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 4) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 5) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 6) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 7) { $expectedOwners=@(Get-OctoberCompatibilityCoverageCartOwners) }
      elseif ($Facts.Stage -eq 8) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 9) { $expectedOwners=@(Get-OctoberCompatibilityInheritedCartTestOwners) }
      elseif ($Facts.Stage -eq 10) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 11) { $expectedOwners=@(Get-OctoberCompatibilityRetentionOwners) }
      elseif ($Facts.Stage -eq 12) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 13) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 14) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 15) { $expectedOwners=@(Get-OctoberCompatibilityScrollRepairOwners) }
      elseif ($Facts.Stage -eq 16) { $expectedOwners=@(Get-OctoberCompatibilityAmendmentOwners) }
      elseif ($Facts.Stage -eq 17) { $expectedOwners=@('apps/mobile/test/work_workspace_layout_safety_test.dart') }
      elseif ($Facts.Stage -eq 18) { $expectedOwners=@('docs/quality/STORE-BUY-COMPATIBILITY-20261008.md') }
      else { return $false }
    }
    'handoff' {
      if ($Facts.Stage -ne 19 -or -not $Facts.ContainsKey('Clean') -or
          $Facts.Clean -isnot [bool] -or -not $Facts.Clean -or
          -not $Facts.ContainsKey('HostQualificationPassed') -or
          $Facts.HostQualificationPassed -isnot [bool] -or
          -not $Facts.HostQualificationPassed) { return $false }
      $expectedOwners=@('docs/quality/STORE-BUY-COMPATIBILITY-20261008.md')
    }
    'integration_admission_authorize' {
      if ($Facts.Stage -ne 19 -or -not $Facts.ContainsKey('Clean') -or
          $Facts.Clean -isnot [bool] -or -not $Facts.Clean -or
          -not $Facts.ContainsKey('HostQualificationPassed') -or
          $Facts.HostQualificationPassed -isnot [bool] -or
          -not $Facts.HostQualificationPassed) { return $false }
      $expectedOwners=@('docs/quality/STORE-BUY-COMPATIBILITY-20261008.md')
    }
    default { return $false }
  }
  # Array equality includes multiplicity; a duplicate cannot hide an omission.
  return (@($Facts.Owners | Sort-Object) -join '|') -ceq
    (@($expectedOwners | Sort-Object) -join '|')
}

