          (ConvertTo-Json -InputObject $binding -Depth 100 -Compress)) 'Pinned shared binding contracts differ.'
      } else { $unionExpected[[string]$binding.id] = $binding }
    }
  }
  Assert-Coordination ($unionExpected.Count -eq 82 -and
