      Assert-Coordination ($derivedPrimary.Count -eq 1 -and @($derivedPrimary[0].owners).Count -eq 101) 'Compatibility N must add exactly four test owners.'
      $octoberCompatibilityTestAdmissionVerified=$true
    }
  }
